    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct coefficients so that the trig ratio is identically k_const for all a
# using identities cos(5a)=16x^5-20x^3+5x and cos(3a)=4x^3-3x with x=cos a.
# Choose k_const, p3, q1, and r5, then solve for u5, s3, t1.
attempts = 0
while True:
    attempts += 1
    if attempts > 1000:
        # Fallback deterministic set if too many retries
        k_const = 7
        p3 = 2
        q1 = 4
        r5 = 2
    else:
        k_const = rng.randint(3, 9)  # nontrivial constant
        p3 = rng.randint(1, 6)
        q1 = rng.randint(1, 6)
        r5 = rng.choice([-3, -2, -1, 1, 2, 3])
    # Enforce non-zero denominator structure (avoid both p3 and q1 zero; already positive)
    # Compute the remaining numerator coefficients to satisfy N(x) = k_const * D(x)
    u5 = -16 * r5
    s3 = 5 * r5 + k_const * p3
    t1 = k_const * (q1 - 3 * p3) - 5 * r5 + 3 * s3  # equals k(q-3p) + 10r + 3kp
    # Choose weights for algebraic part
    w_ab = rng.randint(2, 10)
    w_bc = rng.randint(2, 10)
    # Enforce difficulty: avoid trivial equal weights and k_const=5 with seed-like coefficients
    if w_ab == w_bc:
        continue
    if k_const == 5 and p3 == 1 and q1 == 2 and r5 == 1:
        continue
