    assign = {
        'p3': p3,
        'q1': q1,
        'r5': r5,
        's3': s3,
        't1': t1,
        'u5': u5,
        'k_const': k_const,
        'w_ab': w_ab,
        'w_bc': w_bc
    }
    return assign

