B = 2.0 * (w_bc / 3.0) ** 1.5
s_val = (B + (B ** 2 + 4.0 * A) ** 0.5) / 2.0
C = s_val ** (2.0 / 3.0)
total = k * C
# Enforce difficulty: avoid near-integer answers
if abs(total - round(total)) < 1e-10:
    return (False, None)
# Build exact expression string in LaTeX
# total = k * ((B + sqrt(B^2 + 4A))/2)^{2/3}
# Replace A,B with expressions in w_ab, w_bc.
# B^2 + 4A = 4*(w_bc/3)^3 + 16*w_ab^3/27
